                H("gibbsPMF"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The Gibbs law is a standard Mathlib PMF on actual finite vertex sets. The ambient graph need not be finite. No external probability oracle is used."))), DescribeRole.Definition),
            Describe.Lean(DescribeId.Create("hc-occupation-gibbsoccupation-gibbs-pmf-to-real"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/HardCore/GibbsOccupation.gibbs_pmf_toReal"),
                H("gibbs pmf toReal"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
