                H("gibbs expected card"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("The finite expectation of configuration cardinality under the actual PMF is exactly the first normalized occupation moment."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("hc-occupation-gibbsoccupation-gibbs-vertex-occupied"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/HardCore/GibbsOccupation.gibbs_vertex_occupied"),
