                Blocks(Paragraph(Text("The centered second moment equals the conventional finite PMF variance."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("hc-occupation-gibbsoccupation-variance-eq-moments"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/HardCore/GibbsOccupation.variance_eq_moments"),
                H("variance eq moments"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Expansion of the actual centered variance into its first two raw moments."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("hc-occupation-gibbsoccupation-occupation-variance-nonneg"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/HardCore/GibbsOccupation.occupation_variance_nonneg"),
                H("occupation variance nonneg"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Nonnegativity is proved from squared centered deviations and actual nonnegative masses, not postulated from the derivative formula."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("hc-occupation-gibbsoccupation-mean-occupation-fluctuation-response"),
                DeclarationHandle.Create("D5/S3/StatisticalMechanics/HardCore/GibbsOccupation.mean_occupation_fluctuation_response"),
                H("mean occupation fluctuation response"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(),
                Blocks(Paragraph(Text("Exact fluctuation-response identity. The factor lambda preserves the zero-activity endpoint and expresses differentiation in log activity."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("hc-occupation-gibbsoccupation-mean-occupation-deriv-nonneg"),
